Here's a Node.js function that loads a JSON config file with fallback handling:

```javascript
const fs = require('fs').promises;

async function loadConfig(filePath) {
  try {
    const content = await fs.readFile(filePath, 'utf-8');
    return JSON.parse(content);
  } catch (error) {
    // Return empty object if file doesn't exist
    if (error.code === 'ENOENT') {
      return {};
    }
    // Also return empty object for JSON parse errors
    console.error(`Error loading config from ${filePath}:`, error.message);
    return {};
  }
}

// Usage
loadConfig('./config.json').then(config => {
  console.log(config);
});
```

If you prefer a synchronous version:

