const fs = require('fs');

function loadConfig(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    return JSON.parse(content);
  } catch (error) {
    if (error.code === 'ENOENT') {
      return {};
    }
    console.error(`Error loading config from ${filePath}:`, error.message);
    return {};
  }
}

// Usage
const config = loadConfig('./config.json');
console.log(config);
```

Both versions:
- Catch missing files (`ENOENT` error) and return `{}`
- Also handle JSON parsing errors gracefully
- Log errors for debugging (optional - remove if you prefer silent failures)
- Return an empty object as the fallback in all error cases

Choose async if you're in an async context or modern application, synchronous if you're loading config during startup where blocking is acceptable.

